import { protect, restrictTo } from "@/middleware/auth.middleware";
import { validate, validateParams } from "@/middleware/validation.middleware";
import { Router } from "express";
import { approveDepositRequest, approveWithdrawalRequest, createWalletIfNotExist, deposit, getAllDepositRequests, getAllWithdrawalRequests, getDepositRequestsByTenant, getMyWallet, getMyWithdrawalRequests, getWalletTransactions, rejectDepositRequest, rejectWithdrawalRequest, withdrawal, } from "./wallet.controller";
import { depositRequestParamsSchema, depositSchema, withdrawSchema, withdrawalRequestParamsSchema } from "./wallet.validation";
const router = Router();
router.use(protect);
router.get('/', restrictTo("TENANT", "LANDLORD"), getMyWallet);
router.post('/', restrictTo("TENANT", "LANDLORD"), createWalletIfNotExist);
router.patch('/deposit', restrictTo("TENANT"), validate(depositSchema), deposit);
router.patch('/withdrawal', restrictTo("TENANT", "LANDLORD"), validate(withdrawSchema), withdrawal);
router.patch('/deposit/:id/approve', restrictTo("ADMIN"), validateParams(depositRequestParamsSchema), approveDepositRequest);
router.patch('/deposit/:id/reject', restrictTo("ADMIN"), validateParams(depositRequestParamsSchema), rejectDepositRequest);
router.patch('/withdrawal/:id/approve', restrictTo("ADMIN"), validateParams(withdrawalRequestParamsSchema), approveWithdrawalRequest);
router.patch('/withdrawal/:id/reject', restrictTo("ADMIN"), validateParams(withdrawalRequestParamsSchema), rejectWithdrawalRequest);
router.get('/transactions', restrictTo("TENANT", "LANDLORD"), getWalletTransactions);
router.get('/deposit-requests', restrictTo("ADMIN"), getAllDepositRequests);
router.get('/withdrawal-requests', restrictTo("ADMIN"), getAllWithdrawalRequests);
router.get('/tenant/deposit-requests', restrictTo("TENANT"), getDepositRequestsByTenant);
router.get('/my/withdrawal-requests', restrictTo("TENANT", "LANDLORD"), getMyWithdrawalRequests);
export { router as walletRouter };
